using Astrea.BattleActions;
using NaughtyAttributes;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ActivateStarAbility", menuName = "Data/Battle/Effects/Orion/ActivateStar Ability")]
public class ActivateStarAbility : StarAbility
{
	[Header("Battle Action")]
	[SerializeField]
	protected BattleAction battleAction;

	[SerializeField]
	protected OmenLogic omenLogic;

	[SerializeField]
	protected int actionValue;

	[Header("On Entering Star Actions")]
	[SerializeField]
	private Effect[] onEnteringStarEffects;

	[Header("DisableEnqueueNormalPurifyCorruptCoroutineAction")]
	[SerializeField]
	private bool disableEnqueueNormalPurifyCorruptCoroutineAction;

	[Header("Evil Constellation")]
	[SerializeField]
	protected bool evilConstellation;

	[SerializeField]
	[ShowIf("evilConstellation")]
	protected CurrentCorruptedAnimals currentCorruptedAnimals;

	public int ActionValue => actionValue;

	protected virtual int GetModifiedActionValue()
	{
		return actionValue;
	}

	protected virtual BattleAction GetBattleAction()
	{
		return battleAction;
	}

	protected virtual OmenLogic GetOmenLogic()
	{
		return omenLogic;
	}

	public override string GetLocalizedDescription()
	{
		return GetLocalizedDescriptionWithCastOrb(battleAction.GetActionDescription(actionValue));
	}

	protected string GetLocalizedDescriptionWithCastOrb(string description)
	{
		return Smart.Format(GetCastOrbLocalizedDescription(), description);
	}

	protected string GetLocalizedDescriptionWithoutFormat()
	{
		return "";
	}

	public override void OnEnteringStar()
	{
		PlayerEffects component = ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>();
		for (int i = 0; i < onEnteringStarEffects.Length; i++)
		{
			component.IsEffectActiveWithActivation(onEnteringStarEffects[i]);
		}
		OnActivateStarAbility();
	}

	public override void OnActivateStarAbility()
	{
		PlaySFX();
		CheckDisableEnqueueNormalPurifyCorruptCoroutineAction();
		GetOmenLogic().ActivateOmen(GetBattleAction(), GetModifiedActionValue(), null, evilConstellation ? currentCorruptedAnimals.activeCorruptedAnimals.First() : GetCastOrbSource());
	}

	protected GameObject GetCastOrbSource()
	{
		GameObject result = ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject;
		if (ReferenceSingleton<GameStateManager>.Instance.PreviouslyGameState == ReferenceSingleton<GameStateManager>.Instance.StartPlayerTurnState)
		{
			result = null;
		}
		return result;
	}

	protected void CheckDisableEnqueueNormalPurifyCorruptCoroutineAction()
	{
		if (disableEnqueueNormalPurifyCorruptCoroutineAction)
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.DisableEnqueueNormalPurifyCorruptCoroutineAction = true;
		}
	}
}
